         body='// CoreDnsDemo: runs the five acts\ntry (CoreDns server = CoreDns.start(ShopZone.corefile(),\n        ShopZone.zoneFile(ShopZone.GOOD_ADDRESS, ShopZone.GOOD_TTL))) {\n    act1RealServer(out, server);\n    act2UdpAndTcp(out, server);\n    act3MissingNames(out, server);\n    act4Cache(out, server);\n}\nact5WrongRecord(out);                 // a second server, wrong record',
