    dict(key='25-class-3', kind='code', title='CoreDns — docker run, on loopback only',
         body='// CoreDns: starts and removes the container\nrun(List.of("docker", "run", "-d", "--rm", "--name", name,\n        "-p", "127.0.0.1::53/udp", "-p", "127.0.0.1::53/tcp",\n        "-v", dir + ":/etc/coredns:ro", IMAGE, "-conf", "/etc/coredns/Corefile"));\n...\nrun(List.of("docker", "stop", "-t", "1", name));     // in close()',
         narration='Core D N S starts the pinned CoreDNS image with Docker. [[slnc 300]] Port fifty three is published on loopback only, so nothing outside the machine can ask it. [[slnc 300]] The files are mounted read only, and close stops the container.'),
